/// A real Cargo workspace whose package identity differs from its directory.
fn moved_workspace() -> tempfile::TempDir {
    let ws = workspace(&["core"], true);
    let root = ws.path();
    std::fs::create_dir_all(root.join("substrate/components")).unwrap();
    std::fs::rename(root.join("demo-crate"), root.join("substrate/components/entry")).unwrap();
    write_crate(root, "helper-crate");
    std::fs::rename(root.join("helper-crate"), root.join("substrate/components/support")).unwrap();
    for rel in [DOC_REL, EXTRA_REL] {
        let text = std::fs::read_to_string(root.join(rel)).unwrap();
        std::fs::write(root.join(rel), text.replace("crate: demo-crate", "crate: substrate/components/entry")).unwrap();
        tangle_document(&root.join(rel), root, &PipelineRegistry::default()).unwrap();
    }
    let manifest = root.join("substrate/components/entry/Cargo.toml");
    let text = std::fs::read_to_string(&manifest).unwrap();
    std::fs::write(manifest, format!("{text}\nsupport = {{ package = \"helper-crate\", path = \"../support\" }}\n\
        [target.'cfg(unix)'.build-dependencies]\n\
        helper = {{ package = \"helper-crate\", path = \"../support\" }}\n")).unwrap();
    std::fs::write(root.join("Cargo.toml"),
        "[workspace]\nresolver = \"2\"\nmembers = [\"substrate/components/*\"]\n").unwrap();
    std::fs::write(root.join(PUB_REL),
        publication(&["demo-crate", "helper-crate"], &["core"], true)).unwrap();
    std::fs::create_dir_all(root.join("corpora/x0k")).unwrap();
    std::fs::rename(root.join("ontology"), root.join("corpora/x0k/ontology")).unwrap();
    ws
}

#[test]
fn relocated_packages_project_by_identity_and_retangle_without_drift() {
    let ws = moved_workspace();
    assert!(!ws.path().join("Cargo.lock").exists());
    let out = tempfile::tempdir().unwrap();
    project(ws.path(), out.path()).unwrap();
    assert!(!ws.path().join("Cargo.lock").exists(), "metadata must not write a lock");
    assert!(!out.path().join("substrate").exists());
    let manifest = std::fs::read_to_string(out.path().join("demo-crate/Cargo.toml")).unwrap();
    assert!(manifest.contains("path = \"../helper-crate\""), "{manifest}");
    assert!(!manifest.contains("../support"), "{manifest}");
    let chapter = out.path().join(DOC_REL);
    let text = std::fs::read_to_string(&chapter).unwrap();
    let (env, _) = x0k_folio::colophon::parse_envelope(&text).unwrap();
    assert_eq!(env.tangle.unwrap().crate_name.as_deref(), Some("demo-crate"));
    let generated = out.path().join("demo-crate/src/lib.rs");
    let sidecar = chapter.with_extension("tangle-map.json");
    let code_before = std::fs::read(&generated).unwrap();
    let sidecar_before = std::fs::read(&sidecar).unwrap();
    tangle_document(&chapter, out.path(), &PipelineRegistry::default()).unwrap();
    assert_eq!(std::fs::read(&generated).unwrap(), code_before);
    assert_eq!(std::fs::read(&sidecar).unwrap(), sidecar_before);
    let manifest_before = std::fs::read(out.path().join("demo-crate/Cargo.toml")).unwrap();
    project(ws.path(), out.path()).unwrap();
    assert_eq!(std::fs::read(out.path().join("demo-crate/Cargo.toml")).unwrap(), manifest_before);
    assert_eq!(std::fs::read(&generated).unwrap(), code_before);
    assert_eq!(std::fs::read(&sidecar).unwrap(), sidecar_before);
}

