#[test]
fn relocated_workspace_inherited_paths_are_materialized_and_guarded() {
    let ws = moved_workspace();
    let root = ws.path();
    std::fs::write(root.join("Cargo.toml"),
        "[workspace]\nresolver = \"2\"\nmembers = [\"substrate/components/*\"]\n\
         [workspace.dependencies]\nsupport = { package = \"helper-crate\", path = \"substrate/components/support\", features = [\"inherited\"] }\n").unwrap();
    let helper = root.join("substrate/components/support/Cargo.toml");
    let text = std::fs::read_to_string(&helper).unwrap();
    std::fs::write(helper, format!("{text}\n[features]\ninherited = []\nlocal = []\n")).unwrap();
    let entry = root.join("substrate/components/entry/Cargo.toml");
    let text = std::fs::read_to_string(&entry).unwrap();
    std::fs::write(entry, text.replace(
        "support = { package = \"helper-crate\", path = \"../support\" }",
        "support = { workspace = true, features = [\"local\"] }")).unwrap();
    let out = tempfile::tempdir().unwrap();
    project(root, out.path()).unwrap();
    let text = std::fs::read_to_string(out.path().join("demo-crate/Cargo.toml")).unwrap();
    let manifest = text.parse::<toml_edit::DocumentMut>().unwrap();
    let dep = &manifest["dependencies"]["support"];
    assert_eq!(dep["path"].as_str(), Some("../helper-crate"));
    let features: Vec<_> = dep["features"].as_array().unwrap().iter().filter_map(|v| v.as_str()).collect();
    assert_eq!(features, ["local", "inherited"]);
    assert!(dep.get("workspace").is_none());
    std::fs::write(root.join(PUB_REL), publication(&["demo-crate"], &["core"], true)).unwrap();
    assert!(project_err(root).contains("escaping path dep"));
}

#[test]
fn relocated_target_and_development_dependencies_obey_the_same_closure() {
    for table in ["dev-dependencies", "build-dependencies", "target.'cfg(unix)'.dependencies"] {
        let ws = moved_workspace();
        let manifest = ws.path().join("substrate/components/entry/Cargo.toml");
        let text = std::fs::read_to_string(&manifest).unwrap();
        let head = text.split("[dependencies]").next().unwrap();
        std::fs::write(manifest,
            format!("{head}\n[{table}]\naliased = {{ package = \"helper-crate\", path = \"../support\" }}\n")).unwrap();
        std::fs::write(ws.path().join(PUB_REL), publication(&["demo-crate"], &["core"], true)).unwrap();
        let err = project_err(ws.path());
        assert!(err.contains("aliased") && err.contains("escaping path dep"), "{table}: {err}");
    }
}


fn with_owned_manifest(root: &Path, assembled: bool) -> String {
    let path = root.join(DOC_REL);
    let mut chapter = std::fs::read_to_string(&path).unwrap();
    let manifest = std::fs::read_to_string(root.join("substrate/components/entry/Cargo.toml")).unwrap();
    let fence = char::from(96).to_string().repeat(3);
    if assembled {
        chapter.push_str(&format!("\n{fence}toml {{#manifest file=\"Cargo.toml\"}}\n<<manifest-body>>\n{fence}\n\
            \n{fence}toml {{#manifest-body}}\n{manifest}{fence}\n"));
    } else {
        chapter.push_str(&format!("\n{fence}toml {{#manifest file=\"Cargo.toml\"}}\n{manifest}{fence}\n"));
    }
    std::fs::write(&path, &chapter).unwrap();
    tangle_document(&path, root, &PipelineRegistry::default()).unwrap();
    chapter
}

#[test]
fn projected_manifest_owner_retangles_public_license_paths_and_sidecar() {
    let ws = moved_workspace();
    let canonical = with_owned_manifest(ws.path(), false);
    let out = tempfile::tempdir().unwrap();
    project(ws.path(), out.path()).unwrap();
    let manifest = out.path().join("demo-crate/Cargo.toml");
    let chapter = out.path().join(DOC_REL);
    let sidecar = chapter.with_extension("tangle-map.json");
    let before = std::fs::read(&manifest).unwrap();
    let sidecar_before = std::fs::read(&sidecar).unwrap();
    let public_source = std::fs::read_to_string(&chapter).unwrap();
    assert!(public_source.contains("license = \"MIT\""));
    assert!(public_source.contains("path = \"../helper-crate\""));
    assert!(!public_source.contains("LicenseRef-Proprietary"));
    tangle_document(&chapter, out.path(), &PipelineRegistry::default()).unwrap();
    assert_eq!(std::fs::read(&manifest).unwrap(), before, "re-tangle preserves projected manifest");
    assert_eq!(std::fs::read(&sidecar).unwrap(), sidecar_before, "re-tangle preserves manifest hash");
    project(ws.path(), out.path()).unwrap();
    assert_eq!(std::fs::read(&manifest).unwrap(), before, "reprojection is stable");
    assert_eq!(std::fs::read_to_string(ws.path().join(DOC_REL)).unwrap(), canonical,
        "publication transformations never edit canonical source");
}

