#[test]
fn organized_layout_retangles_and_preserves_canonical_source_mapping() {
    let ws = workspace(&[], true);
    let publication_path = ws.path().join(PUB_REL);
    let text = std::fs::read_to_string(&publication_path).unwrap();
    std::fs::write(&publication_path, text.replacen("x0k:\n", "x0k:\n  repositoryLayout: organized\n", 1)).unwrap();
    let out = tempfile::tempdir().unwrap();
    let report = project(ws.path(), out.path()).unwrap();
    let root = out.path();
    assert!(root.join("crates/demo-crate/Cargo.toml").is_file());
    assert!(!root.join("demo-crate").exists());
    let chapter = root.join("implementation/demo/colophon.md");
    assert!(chapter.is_file());
    let code = std::fs::read_to_string(root.join("crates/demo-crate/src/lib.rs")).unwrap();
    assert!(code.contains("from implementation/demo/colophon.md"), "{code}");
    assert_eq!(report.literate_docs[0], std::path::PathBuf::from("implementation/demo/colophon.md"));
    let prov: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(root.join("PROVENANCE.json")).unwrap()).unwrap();
    assert_eq!(prov["path_map"]["implementation/demo/colophon.md"].as_str(), Some(DOC_REL));
    let manifest = std::fs::read_to_string(root.join("crates/demo-crate/Cargo.toml")).unwrap();
    assert!(manifest.contains("../../README.md"), "{manifest}");
    let sidecar_path = chapter.with_extension("tangle-map.json");
    let before = std::fs::read(&sidecar_path).unwrap();
    tangle_document(&chapter, root, &PipelineRegistry::default()).unwrap();
    assert_eq!(before, std::fs::read(sidecar_path).unwrap());
    assert_eq!(code, std::fs::read_to_string(root.join("crates/demo-crate/src/lib.rs")).unwrap());
    assert!(std::fs::read_to_string(root.join("tools/ci")).unwrap().contains("-- tangle implementation --workspace ."));
    let second = tempfile::tempdir().unwrap();
    project(ws.path(), second.path()).unwrap();
    assert_eq!(std::fs::read(root.join("PROVENANCE.json")).unwrap(), std::fs::read(second.path().join("PROVENANCE.json")).unwrap());
}
